CREATE OR REPLACE FUNCTION public.room_for(p_base double precision, p_rare text)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
AS $function$
begin
  return (
select case when step = 0 or plain <= 0 then plain
              else plain + greatest(step, floor(plain * rarity_room() * step + 0.5)::int) end
